117	/// After a video patch has merged: a patch that names a built-in `kind` and
118	/// no `media` drops a stored `media` (the built-in replaces the LUT), and a
119	/// patch that names `media` on a built-in kind is refused.
120	pub(crate) fn normalise_look(props: &mut VideoProps, patch: &Value) -> Result<(), String> {
121	    let Some(Value::Object(asked)) = patch.get("look") else {
122	        return Ok(());
123	    };
124	    let Some(look) = props.look.as_mut() else {
125	        return Ok(());
126	    };
127	    if look.kind == LookKind::Lut {
128	        return Ok(());
129	    }
130	    let names_media = asked.get("media").is_some_and(|media| !media.is_null());
131	    if names_media {
132	        return Err(media_goes_with_lut(look.kind));
133	    }
134	    if asked.get("kind").is_some_and(|kind| !kind.is_null()) {
135	        look.media = None;
136	    }
137	    Ok(())
138	}
