148	/// absorb list, after the source's media.
149	pub(crate) fn look_media_ids(clip: &Clip) -> Vec<u32> {
150	    let mut ids: Vec<u32> = Vec::new();
151	    let base = clip.video.as_ref().and_then(|video| video.look?.media);
152	    let ends = clip.actions.iter().filter_map(|action| {
153	        let media = action.end.get("video")?.get("look")?.get("media")?;
154	        u32::try_from(media.as_u64()?).ok()
155	    });
156	    for id in base.into_iter().chain(ends) {
157	        if !ids.contains(&id) {
158	            ids.push(id);
159	        }
160	    }
161	    ids
162	}
