331	    /// (`outputSettings: nil`): an x265 track's first buffer holds no sample,
332	    /// so empty buffers are skipped. The reader is cancelled once it has one.
333	    private static func firstSample(of track: AVAssetTrack, in asset: AVAsset) -> Data? {
334	        guard let reader = try? AVAssetReader(asset: asset) else { return nil }
335	        let output = AVAssetReaderTrackOutput(track: track, outputSettings: nil)
336	        output.alwaysCopiesSampleData = false
337	        guard reader.canAdd(output) else { return nil }
338	        reader.add(output)
339	        defer { reader.cancelReading() }
340	        guard reader.startReading() else { return nil }
341	        while let buffer = output.copyNextSampleBuffer() {
342	            guard let block = CMSampleBufferGetDataBuffer(buffer) else { continue }
343	            let length = CMBlockBufferGetDataLength(block)
344	            guard length > 0 else { continue }
345	            var bytes = Data(count: length)
346	            let status = bytes.withUnsafeMutableBytes { out -> OSStatus in
347	                guard let base = out.baseAddress else { return -1 }
348	                return CMBlockBufferCopyDataBytes(
349	                    block, atOffset: 0, dataLength: length, destination: base)
350	            }
351	            return status == noErr ? bytes : nil
352	        }
353	        return nil
354	    }
